import {jobs,jobById} from './data.js';
import {emptyState,readState,writeState,toggleSaved,validatePreferences,submitDemo} from './model.js';
import {newApplicationDraft} from './applications.js';
import * as v from './views.js';
import {relevantWorkspaceEvent,writeFeedback} from './workspace.js';
const preview=new URLSearchParams(location.search).has('preview'),memory=new Map();let storage;try{storage=preview?{getItem:k=>memory.get(k)||null,setItem:(k,x)=>memory.set(k,x)}:localStorage;}catch{storage={getItem(){throw Error()},setItem(){throw Error()}};}
let feedbackOrigin=null,preferenceDraft=null;
const noteDrafts=new Map(),openNotes=new Set();
let {state:s,error:warning}=readState(storage),selection=[],undo=null,errors={},drafts=new Map(),requestIds=new Map();
if(preview&&new URLSearchParams(location.search).get('case')==='shortlist'){s.saved=['north','morrow','cedar'];writeState(storage,s);}
if(preview&&new URLSearchParams(location.search).get('case')==='recorded'){const result=submitDemo(storage,s,'north',{answer:'Preview fixture: clarify complex workflows.',acknowledged:true},'DEMO-preview-0001','2026-10-21T12:00:00Z');s=result.state;}
if(preview&&new URLSearchParams(location.search).get('case')==='draft-notes'){s.saved=['north','morrow'];noteDrafts.set('north',{note:'QA unsaved private note. No information is shared with employers.',stage:'exploring'});openNotes.add('north');writeState(storage,s);}
if(preview&&new URLSearchParams(location.search).get('case')==='storage-blocked')storage.setItem=()=>{throw Error('QA blocked storage');};
// Isolated review fixtures; never written to the persistent candidate workspace.
if(preview&&new URLSearchParams(location.search).get('case')==='morrow')s.passed=['north'];
if(preview&&new URLSearchParams(location.search).get('case')==='gap')s.evidence.systems='none';
const root=document.querySelector('#app'),announce=message=>document.querySelector('#announcer').textContent=message;
// Use measured fixed-bar heights, including enlarged text, rather than guesses.
function syncInsets(){
 const height=(selector,position)=>{const el=document.querySelector(selector);return el&&getComputedStyle(el).position===position?el.getBoundingClientRect().height:0;};
 const values={'--nav-block':height('.bottom-nav','fixed'),'--actions-block':height('.discovery-actions','fixed'),'--header-block':height('.topbar','sticky'),'--feedback-block':height('#toast','fixed')};
 for(const [key,value] of Object.entries(values))document.documentElement.style.setProperty(key,value+'px');
}
const layoutObserver=new ResizeObserver(syncInsets);
function observeInsets(){layoutObserver.disconnect();for(const selector of ['.bottom-nav','.discovery-actions','.topbar','#toast']){const el=document.querySelector(selector);if(el)layoutObserver.observe(el);}syncInsets();}
function dismissFeedback(){document.querySelector('#toast').hidden=true;syncInsets();const target=feedbackOrigin?.isConnected&&feedbackOrigin.getClientRects().length?feedbackOrigin:document.querySelector('#main');target?.focus();}

const route=()=>{const [path,query='']=(location.hash||'#/discover').slice(2).split('?');const [name,id]=path.split('/');return {name,id,p:new URLSearchParams(query)};};
function persist(next){s=next;warning=writeState(storage,s);}
function toast(text,withUndo=false){feedbackOrigin=document.activeElement!==document.body?document.activeElement:document.querySelector('#main');const box=document.querySelector('#toast');box.hidden=false;box.className='toast';box.innerHTML=`<span>${v.e(text)}</span>${withUndo?'<button data-action="undo">Undo</button>':'<button data-action="dismiss">Dismiss</button>'}`;announce(text);syncInsets();}
function focusReplacement(action,id){const target=document.querySelector(`[data-action="${action}"][data-id="${id}"]`)||document.querySelector(`[data-action="${action}"]`)||document.querySelector('.empty h2')||document.querySelector('#main');if(target&&!target.matches('button,a,input,select,textarea'))target.setAttribute('tabindex','-1');target?.focus();}
function render(focus=false){const r=route();selection=selection.filter(id=>s.saved.includes(id));let content;const j=jobById(r.id);switch(r.name){case 'discover':content=v.discover(s);break;case 'search':content=v.search(s,r.p);break;case 'saved':content=v.saved(s,selection,noteDrafts,openNotes);break;case 'compare':content=v.compare(s,r.p);break;case 'profile':content=v.profile(s,errors,preferenceDraft);break;case 'applications':content=v.applications(s);break;case 'job':content=j?v.title('Role details','Examine the evidence before deciding.',v.link('Back',r.p.get('from')==='search'?'#/search?'+(r.p.get('back')||''):'#/'+(r.p.get('from')||'discover'),'quiet'))+`<div class="narrow">${v.details(j,s)}</div>`:null;break;case 'apply':if(j&&!drafts.has(j.id))drafts.set(j.id,newApplicationDraft());content=j?v.apply(j,s,drafts.get(j.id),errors):null;break;case 'receipt':{const a=s.applications.find(a=>a.id===r.id);content=a?v.receipt(a):null;break;}}
if(!content)content=v.title('This page is unavailable','The link or local receipt may no longer exist.')+v.empty('Return to your workspace.','Demo receipts are stored only in the browser that created them.',v.link('Discover roles','#/discover','primary'));
root.innerHTML=v.shell(content,r.name,warning,preview);document.title=`ALIGN · ${r.name[0]?.toUpperCase()+r.name.slice(1)}`;document.body.dataset.view=r.name;observeInsets();if(focus){(document.querySelector('.error-summary')||document.querySelector('h1')||document.querySelector('#main'))?.focus();}document.documentElement.dataset.ready='true';}
window.addEventListener('hashchange',()=>{document.querySelector('#toast').hidden=true;errors={};preferenceDraft=null;render(true);window.scrollTo(0,0);});
function rememberFocus(){const el=document.activeElement;if(!el||el===document.body)return null;return {id:el.id,select:el.dataset.select,action:el.dataset.action,job:el.dataset.id,href:el.getAttribute('href'),start:el.selectionStart,end:el.selectionEnd};}
function restoreFocus(saved){if(!saved)return;const target=(saved.id&&document.getElementById(saved.id))||(saved.select&&document.querySelector(`[data-select="${CSS.escape(saved.select)}"]`))||(saved.action&&document.querySelector(`[data-action="${CSS.escape(saved.action)}"][data-id="${CSS.escape(saved.job||'')}"]`))||(saved.href&&document.querySelector(`a[href="${CSS.escape(saved.href)}"]`))||document.querySelector('#main');target?.focus({preventScroll:true});if(target?.setSelectionRange&&typeof saved.start==='number'&&['TEXTAREA','INPUT'].includes(target.tagName)&&target.type!=='number')target.setSelectionRange(saved.start,saved.end);}
window.addEventListener('storage',event=>{
 if(!relevantWorkspaceEvent(event,storage,preview))return;
 const focus=rememberFocus(),hadUndo=!!undo,latest=readState(storage);undo=null;
 if(!latest.error)s=latest.state;warning=latest.error;
 if(!['apply','profile'].includes(route().name)){render();restoreFocus(focus);}
 const removedDraft=[...noteDrafts.keys()].some(id=>!s.saved.includes(id));
 toast(latest.error?'Browser storage could not be read. This visit and your unsaved drafts are kept.':removedDraft?'A role with unsaved notes was removed in another tab. Its draft is kept for this visit; save the role again to continue editing.':hadUndo?'Workspace updated in another tab. Earlier Undo is no longer available.':'Workspace updated in another tab. Unsaved notes are still here.');
});
function captureNoteDraft(target){const form=target.closest('form[data-note]');if(form){noteDrafts.set(form.dataset.note,{note:form.elements.note.value,stage:form.elements.stage.value});openNotes.add(form.dataset.note);}}
document.addEventListener('toggle',event=>{const panel=event.target;if(panel.matches?.('[data-note-panel]')&&panel.isConnected){if(panel.open)openNotes.add(panel.dataset.notePanel);else openNotes.delete(panel.dataset.notePanel);}},true);
document.addEventListener('input',event=>{captureNoteDraft(event.target);const form=event.target.closest('#application-form');if(form){drafts.set(form.dataset.id,{answer:form.elements.answer.value,acknowledged:form.elements.acknowledged.checked});}});
document.addEventListener('change',event=>{captureNoteDraft(event.target);if(event.target.matches('[data-select]')){const id=event.target.dataset.select;if(event.target.checked&&selection.length>=3){event.target.checked=false;toast('Compare up to three roles.');return;}selection=event.target.checked?[...selection,id]:selection.filter(x=>x!==id);render();document.querySelector(`[data-select="${id}"]`)?.focus();announce(`${selection.length} roles selected for comparison.`);}});
document.addEventListener('click',event=>{const errorLink=event.target.closest('[data-error-target]');if(errorLink){event.preventDefault();document.getElementById(errorLink.dataset.errorTarget)?.focus();return;}if(event.target.closest('.skip')){event.preventDefault();document.querySelector('#main').focus();return;}const target=event.target.closest('[data-action]');if(!target)return;const {action,id}=target.dataset;switch(action){case 'save':{undo=structuredClone(s);const had=s.saved.includes(id);if(had){noteDrafts.delete(id);openNotes.delete(id);}persist(toggleSaved(s,id));render();focusReplacement('save',id);toast(writeFeedback(warning,had?'Removed from Saved. Note and stage can be restored with Undo.':'Saved privately. No application sent.'),true);break;}case 'pass':undo=structuredClone(s);persist({...s,passed:[...new Set([...s.passed,id])]});render();focusReplacement('pass',id);toast(writeFeedback(warning,'Passed. The role is still available in Search.'),true);break;case 'undo':if(undo){persist({...undo,applications:s.applications});undo=null;render();focusReplacement('save',id);toast(writeFeedback(warning,'Last shortlist or pass change undone.'));}break;case 'dismiss':dismissFeedback();break;case 'reset-passes':persist({...s,passed:[]});render();focusReplacement('pass');toast(writeFeedback(warning,'Passed roles returned to Discover.'));break;case 'preview':{const r=route();r.p.set('selected',id);history.replaceState(null,'','#/search?'+r.p);render();document.querySelector('.detail-preview')?.scrollTo(0,0);announce('Previewing '+jobById(id).title+' at '+jobById(id).employer);document.querySelector(`[data-action="preview"][data-id="${id}"]`)?.focus();break;}case 'compare':if(selection.length>=2)location.hash='#/compare?ids='+selection.join(',');break;}});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target;if(form.id==='search-form'){const p=new URLSearchParams(new FormData(form));location.hash='#/search?'+p;return;}if(form.id==='profile-form'){const data=new FormData(form),result=validatePreferences(Object.fromEntries(data));const evidence=Object.fromEntries(Object.keys(s.evidence).map(k=>[k,data.get('e-'+k)]));errors=result.errors;if(Object.keys(errors).length){preferenceDraft={preferences:{arrangement:data.get('arrangement'),minimumPay:data.get('minimumPay')},evidence};render(true);return;}preferenceDraft=null;persist({...s,preferences:result.value,evidence});render();document.querySelector('#profile-form button')?.focus({preventScroll:true});toast(writeFeedback(warning,'Preferences and evidence updated. All Decision Briefs now use these values.'));return;}if(form.dataset.note){const id=form.dataset.note;if(!s.saved.includes(id)){toast('This role was removed from Saved in another tab. Your draft is kept for this visit; save the role again before saving the note.');return;}const focus=rememberFocus(),draft={note:form.elements.note.value,stage:form.elements.stage.value};persist({...s,notes:{...s.notes,[id]:draft.note},stages:{...s.stages,[id]:draft.stage}});if(warning)noteDrafts.set(id,draft);else noteDrafts.delete(id);openNotes.add(id);render();restoreFocus(focus);toast(writeFeedback(warning,'Private note and stage saved.'));return;}if(form.id==='application-form'){const id=form.dataset.id,draft={answer:form.elements.answer.value,acknowledged:form.elements.acknowledged.checked};drafts.set(id,draft);if(!requestIds.has(id))requestIds.set(id,'DEMO-'+crypto.randomUUID());const result=submitDemo(storage,s,id,draft,requestIds.get(id),new Date().toISOString());errors=result.errors||{};if(!result.record){render(true);return;}s=result.state;drafts.delete(id);errors={};location.hash='#/receipt/'+result.record.id;announce('Demo saved in this browser. Employer delivery: not sent.');}});
render();
